{"witnessCode": "import normalizeUrl from '../index.js';
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

describe('WWW strip regression', () => {
  it('should strip www. from single-character second-level domain', () => {
    const input = 'http://www.a.com';
    const expected = 'http://a.com';
    const actual = normalizeUrl(input, { stripWWW: true });
    assert.strictEqual(actual, expected);
  });
});"}
